using Microsoft.EntityFrameworkCore;
namespace DadoHome.Api.Data;
public class DadoDbContext(DbContextOptions<DadoDbContext> options):DbContext(options){public DbSet<Product> Products=>Set<Product>();public DbSet<Customer> Customers=>Set<Customer>();public DbSet<StaffUser> StaffUsers=>Set<StaffUser>();public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderItem> OrderItems=>Set<OrderItem>();public DbSet<Wallet> Wallets=>Set<Wallet>();public DbSet<WalletEntry> WalletEntries=>Set<WalletEntry>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Product>().HasIndex(x=>x.Sku).IsUnique();b.Entity<Customer>().HasIndex(x=>x.Phone).IsUnique();b.Entity<StaffUser>().HasIndex(x=>x.Phone).IsUnique();b.Entity<Wallet>().HasIndex(x=>x.CustomerId).IsUnique();b.Entity<WalletEntry>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<Product>().Property(x=>x.Price).HasPrecision(18,2);b.Entity<Order>().Property(x=>x.Total).HasPrecision(18,2);}}
public class Product{public Guid Id{get;set;}public string Sku{get;set;}="";public string Name{get;set;}="";public string Category{get;set;}="Товары для дома";public decimal Price{get;set;}public int Stock{get;set;}public bool IsActive{get;set;}=true;public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
public class Customer{public Guid Id{get;set;}public string Phone{get;set;}="";public string? Name{get;set;}public bool TwoFactorEnabled{get;set;}=true;public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
public class StaffUser{public Guid Id{get;set;}public string Phone{get;set;}="";public string Name{get;set;}="";public string Role{get;set;}="Support";public bool IsActive{get;set;}=true;public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
public class Order{public Guid Id{get;set;}public Guid CustomerId{get;set;}public string Number{get;set;}="";public string Status{get;set;}="Created";public string DeliveryMethod{get;set;}="Courier";public string PaymentMethod{get;set;}="";public decimal Total{get;set;}public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
public class OrderItem{public Guid Id{get;set;}public Guid OrderId{get;set;}public Guid ProductId{get;set;}public string ProductName{get;set;}="";public string Variant{get;set;}="";public int Quantity{get;set;}public decimal UnitPrice{get;set;}}
public class Wallet{public Guid Id{get;set;}public Guid CustomerId{get;set;}public string Currency{get;set;}="TJS";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
public class WalletEntry{public Guid Id{get;set;}public Guid WalletId{get;set;}public Guid? OrderId{get;set;}public decimal Amount{get;set;}public string Type{get;set;}="";public string Status{get;set;}="Pending";public string ExternalId{get;set;}="";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
public class AuditLog{public Guid Id{get;set;}public string ActorId{get;set;}="";public string Role{get;set;}="";public string Action{get;set;}="";public string Entity{get;set;}="";public string EntityId{get;set;}="";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
